//! Fixed-shape periodic tilings stored as data: a lattice (`a1`, `a2`) and the polygons of one
//! unit cell. The Archimedean tilings JETCARP does not hand-code come from
//! `data/tilings/archimedean.json` (generated by `tools/gen_archimedean.py`); the 1,248
//! k-uniform tilings (k ≤ 6) are in `data/tilings/kuniform.json` (`tools/gen_kuniform.py`, exact
//! Z[ω] cells decoded by [`crate::zomega`]). The `periodic` family uses the same layout inline.

use crate::geom::P;
use serde::{Deserialize, Serialize};
use std::sync::OnceLock;

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct CatalogTiling {
    pub id: String,
    pub name: String,
    #[serde(default)]
    pub group: String,
    /// Number of vertex orbits (k-uniform), when known.
    #[serde(default)]
    pub k: u32,
    #[serde(default)]
    pub note: String,
    pub a1: P,
    pub a2: P,
    pub polys: Vec<Vec<P>>,
}

#[derive(Deserialize)]
struct File {
    tilings: Vec<crate::zomega::Entry>,
}

static SOURCES: &[&str] = &[
    include_str!("../data/tilings/archimedean.json"),
    include_str!("../data/tilings/kuniform.json"),
];

pub fn all() -> &'static [CatalogTiling] {
    static ALL: OnceLock<Vec<CatalogTiling>> = OnceLock::new();
    ALL.get_or_init(|| {
        let mut v = Vec::new();
        for s in SOURCES {
            let f: File = serde_json::from_str(s).expect("embedded tiling catalog");
            v.extend(f.tilings.into_iter().map(|e| e.into_tiling()));
        }
        v
    })
}

pub fn get(id: &str) -> Option<&'static CatalogTiling> {
    all().iter().find(|t| t.id == id)
}

/// Unit cell from `periodic` family parameters: inline `{a1, a2, polys}` or `{catalog: id}`.
pub fn from_params(p: &serde_json::Value) -> Result<(P, P, Vec<Vec<P>>), String> {
    if let Some(id) = p.get("catalog").and_then(|v| v.as_str()) {
        let t = get(id).ok_or_else(|| format!("no catalog tiling '{id}'"))?;
        return Ok((t.a1, t.a2, t.polys.clone()));
    }
    let pt = |v: &serde_json::Value| -> Option<P> {
        let a = v.as_array()?;
        Some([a.first()?.as_f64()?, a.get(1)?.as_f64()?])
    };
    let a1 = p.get("a1").and_then(pt).ok_or("periodic tiling needs a1")?;
    let a2 = p.get("a2").and_then(pt).ok_or("periodic tiling needs a2")?;
    let polys: Option<Vec<Vec<P>>> = p
        .get("polys")
        .and_then(|v| v.as_array())
        .ok_or("periodic tiling needs polys")?
        .iter()
        .map(|poly| poly.as_array()?.iter().map(pt).collect())
        .collect();
    let polys = polys.ok_or("polys must be lists of [x, y] points")?;
    if polys.is_empty() || polys.iter().any(|p| p.len() < 3) {
        return Err("each polygon needs at least 3 corners".into());
    }
    Ok((a1, a2, polys))
}
